package totals

import "sync"

// Snapshot is a value observation of accepted updates.
type Snapshot struct {
	Count int64
	Sum   int64
}

// Totals collects updates. Its zero value is usable; do not copy after use.
type Totals struct {
	mu    sync.Mutex
	count int64
	sum   int64
}

// Add accepts one update.
func (t *Totals) Add(delta int64) {
	t.mu.Lock()
	t.count++
	t.sum += delta
	t.mu.Unlock()
}

// Snapshot returns current totals.
func (t *Totals) Snapshot() Snapshot {
	t.mu.Lock()
	snapshot := Snapshot{Count: t.count, Sum: t.sum}
	t.mu.Unlock()
	return snapshot
}

substitution.new:
package totals

import (
	"runtime"
	"sync/atomic"
)

type Snapshot struct {
	Count int64
	Sum   int64
}
type Totals struct{ count, sum atomic.Int64 }

func (t *Totals) Add(delta int64) { t.count.Add(1); runtime.Gosched(); t.sum.Add(delta) }
func (t *Totals) Snapshot() Snapshot {
	count := t.count.Load()
	runtime.Gosched()
	return Snapshot{count, t.sum.Load()}
}

